import { imImport, waitForStockIm, fallbackReplySnippet, fallbackEmojiHex, fallbackRecentSmiles, fallbackRecentSmileClick, fallbackPeerAvatar, ensureVideoPreviews, syncBodyNoScroll, syncBodyPeerWindow, isCompactMode } from './shared.js';
import { isMobileViewport } from './mobile-mode.js';
import { createPeerInfoView } from './components/peer-info-view.js';
import { createPinnedMessageBar } from './components/pinned-message-bar.js';
import { createAttachmentMenu } from './components/attachment-menu.js';
import { createInputArea } from './components/input-area.js';
import { createStockInputArea } from './components/input-area-stock.js';
import { createActionsBar } from './components/actions-bar.js';
import { installPeerWindow } from './components/peer-window.js';
import { installClassicTabBar } from './components/classic-tab-bar.js';
import { installConversationsRenderer } from './components/conversations-page.js';
import { installFastChatsRenderer } from './components/fastchats.js';

let installed = false;

let lastRenderError = null;

function logRenderErrorOnce(prefix, e) {
    const key = String(prefix) + ' :: ' + String((e && e.message) || e);
    if (key === lastRenderError) {
        return;
    }
    lastRenderError = key;
    console.error(prefix, e);
}

const ATTACHMENT_LOADER_IMG = 'img[src$="loading_mini.gif"]';
const ATTACHMENT_LOADER_SCOPE = '.messenger-app--messages---message ._content';

function syncImAppbarBack() {
    const appbar = document.getElementById('appbar');
    const menu = document.getElementById('mobileMenuTrigger');
    if (!appbar || !menu) return;

    const im = window.im;
    const onIm = isMobileViewport() && /^\/im(?:\/|$)/.test(location.pathname)
        && !!document.querySelector('#im_container');
    const tab = onIm ? im?.getSelectedTab?.() : null;
    const tabId = tab?.getPageId?.();
    const chatHasBack = tabId === 'messenger' && !!im?.messenger?.getCurrentChat?.();
    const showBack = !!tabId && tabId !== 'conversations' && !chatHasBack;
    const title = appbar.querySelector('.appbar-title');
    if (title) {
        if (tab) {
            if (title._vkifyImOriginalHTML === undefined) title._vkifyImOriginalHTML = title.innerHTML;
            const name = chatHasBack ? im.messenger.getCurrentChat()?.peer?.getName?.() : null;
            title.textContent = name || tab.getName?.() || '';
        } else if (title._vkifyImOriginalHTML !== undefined) {
            title.innerHTML = title._vkifyImOriginalHTML;
            delete title._vkifyImOriginalHTML;
        }
        title.hidden = chatHasBack;
    }
    let back = appbar.querySelector('.appbar-back');
    if (!back && showBack) {
        back = document.createElement('button');
        back.className = 'appbar-back';
        back.type = 'button';
        back.setAttribute('aria-label', typeof window.tr === 'function' ? window.tr('back') : 'Back');
        back.innerHTML = '<svg viewBox="0 0 28 28" width="28" height="28" fill="currentColor"><use href="#arrow-left-outline-28"></use></svg>';
        appbar.insertBefore(back, menu);
    }
    if (back) back.hidden = !showBack;
    menu.hidden = showBack || chatHasBack;
}

async function onImAppbarBack(e) {
    if (!e.target.closest?.('.appbar-back')) return;
    e.preventDefault();
    const im = window.im;
    if (!isMobileViewport() || !/^\/im(?:\/|$)/.test(location.pathname) || !im) return;

    const tab = im.getSelectedTab?.();
    const page = tab?.render_class;
    const tabId = tab?.getPageId?.();
    try {
        if (typeof page?.onCancel === 'function') {
            await page.onCancel(e);
        } else if (tabId === 'contact' && im.messenger?.getCurrentChat?.()) {
            await im.messenger.view?.togglePeerInfo?.();
        } else if (tabId === 'friends' && page?.options?.referrer === 'add_new') {
            const peer = im.state?.getCurrentConvo?.()?.peer;
            await im.openTabByName('contact', false, { peer });
        } else {
            await im.openTabByName(im.messenger?.getCurrentChat?.() && tabId !== 'friends'
                ? 'messenger' : 'conversations');
        }
    } catch (err) {
        console.error('vkify16 | IM back failed:', err);
    }
}

// Upstream renders a bare loading_mini.gif while a message's attachments are
// being lazy-loaded. Hide the img in place (preact owns and removes it on the
// next diff) and show the LoaderUtils .pr spinner instead. Runs after each
// render so orphan spinners from upstream removals are cleaned up too.
function syncAttachmentLoaders(container) {
    if (!container || !window.LoaderUtils) {
        return;
    }
    container.querySelectorAll(`${ATTACHMENT_LOADER_SCOPE} > ${ATTACHMENT_LOADER_IMG}`).forEach((img) => {
        img.style.display = 'none';
        const pr = window.LoaderUtils.show(img.parentElement, { size: 'medium', className: 'vkify-att-loader' });
        if (pr && pr.length) {
            pr.addClass('vkify-att-loader');
        }
    });
    container.querySelectorAll(`${ATTACHMENT_LOADER_SCOPE} > .pr.vkify-att-loader`).forEach((pr) => {
        if (!pr.parentElement.querySelector(`:scope > ${ATTACHMENT_LOADER_IMG}`)) {
            pr.remove();
        }
    });
}

export async function installMessengerRenderer() {
    if (installed) {
        return;
    }
    installed = true;

    await waitForStockIm();

    const moduleUrls = [
        './pages/messenger.js',
        './components/message.js',
        './components/common.js',
        './components/render.js',
        '../node_modules/preact/dist/preact.mjs',
    ];
    const loaded = [];
    for (const u of moduleUrls) {
        try {
            loaded.push(await imImport(u));
        } catch (e) {
            console.error('vkify16 | Failed to load', u, ':', e && e.message, e);
            loaded.push(null);
        }
    }
    const [messengerPagesMod, messageMod, commonMod, renderMod, preactMod] = loaded;

    const { MessengerPage } = messengerPagesMod || {};
    const { MessageListView } = messageMod || {};
    const { ErrorConversation, MentionAutocomplete } = commonMod || {};
    const {
        PeerAvatar: UpstreamPeerAvatar,
        getReplySnippet: upstreamReplySnippet,
        getEmojiHex: upstreamEmojiHex,
        getDisplayRecentSmiles: upstreamRecentSmiles,
        onRecentSmileClick: upstreamRecentSmileClick,
    } = commonMod || {};
    const { html, render } = renderMod || {};
    const { h, Fragment } = preactMod || {};

    if (!MessengerPage || !MessageListView || !ErrorConversation || !html || !render || !h || !Fragment) {
        console.error('vkify16 | messenger renderer aborted: module exports missing', {
            messengerPagesMod, messageMod, commonMod, renderMod, preactMod,
        });
        return;
    }

    const origMessengerRender = MessengerPage.prototype.render;
    const origGetCurrentAttachments = MessengerPage.prototype.getCurrentAttachments;

    const getReplySnippet = upstreamReplySnippet || fallbackReplySnippet;
    const getEmojiHex = upstreamEmojiHex || fallbackEmojiHex;
    const getDisplayRecentSmiles = upstreamRecentSmiles || fallbackRecentSmiles;
    const onRecentSmileClick = upstreamRecentSmileClick || fallbackRecentSmileClick;
    const PeerAvatar = UpstreamPeerAvatar || ((props) => fallbackPeerAvatar({ html, ...props }));

    const tr = (typeof window.tr === 'function' ? window.tr : (key) => key);

    const AttachmentMenu = createAttachmentMenu({ html, tr });
    const VkInputArea = createInputArea({ html, tr, AttachmentMenu, getReplySnippet, getEmojiHex, MentionAutocomplete });
    const StockInputArea = createStockInputArea({ html, tr, getDisplayRecentSmiles, onRecentSmileClick, getEmojiHex, getReplySnippet, PeerAvatar, MentionAutocomplete });
    const PeerInfoView = createPeerInfoView({ html, tr, PeerAvatar });
    const PinnedMessageBar = createPinnedMessageBar({ html, tr });
    const VkActionsBar = createActionsBar({ html, tr });

    // VK empty state: icon over a muted hint, plus a cancel button when forwarding.
    const VkEmptyConversation = ({ isForward = false, onCancel = null }) => html`
        <div class="im-empty-conversation ${isForward ? 'is-forward' : ''}">
            <div class="im-empty-conversation--content">
                <div class="im-empty-conversation--image"></div>
                <div class="im-empty-conversation--text">${tr(isForward ? 'im_forward_dialog_hint' : 'im_empty_dialog_hint')}</div>
                ${isForward ? html`<button type="button" class="button im-page--cancel-fwd" onClick=${onCancel}>${tr('cancel')}</button>` : ''}
            </div>
        </div>
    `;

    const use2018 = window.vkify ? window.vkify.getSetting('mode2018') : false;
    const InputAreaComponent = (use2018 || isMobileViewport()) ? VkInputArea : StockInputArea;

    installPeerWindow({ h, preactMod, commonMod });
    await installClassicTabBar({ html, render, commonMod });
    await installConversationsRenderer({ html, render, h, Fragment, commonMod });
    await installFastChatsRenderer({ html, render, commonMod, messageMod });

    const conversations = window.im?.conversations;
    if (conversations && typeof conversations.update === 'function') {
        const originalUpdate = conversations.update;
        conversations.update = function vkifyConversationsUpdate() {
            const result = originalUpdate.apply(this, arguments);
            refreshPeerTabs(window.im?.messenger);
            return result;
        };
    }

    // Upstream selectTab() logs a TypeError on the first tab selection because
    // getSelectedTab() is null until selectedTabId is set a few lines below.
    // Shadow the method for the duration of the call so the diagnostic oldId
    // read stays silent without patching upstream sources.
    const ImClass = window.im_class || (window.im && window.im.constructor);
    if (ImClass && ImClass.prototype && typeof ImClass.prototype.selectTab === 'function') {
        const emptyTab = { getId: () => 0, getPageId: () => null };
        const origSelectTab = ImClass.prototype.selectTab;
        ImClass.prototype.selectTab = function vkifySelectTab(tab) {
            if (this.getSelectedTabId?.() === 'messenger') window.uiActionsMenu?.closeAll?.();
            const getSelected = this.getSelectedTab;
            this.getSelectedTab = () => getSelected.call(this) || emptyTab;
            try {
                const result = origSelectTab.call(this, tab);
                Promise.resolve(result).then(() => syncBodyPeerWindow()).catch(() => {});
                return result;
            } finally {
                delete this.getSelectedTab;
            }
        };
    }
    if (ImClass && ImClass.prototype && typeof ImClass.prototype.updateTabs === 'function') {
        // close() skips selectTab; updateTabs covers the contact tab closing
        const origUpdateTabs = ImClass.prototype.updateTabs;
        ImClass.prototype.updateTabs = function vkifyUpdateTabs() {
            try {
                return origUpdateTabs.apply(this, arguments);
            } finally {
                syncBodyPeerWindow();
                syncImAppbarBack();
            }
        };
    }
    window.vkify?.onPage(syncImAppbarBack);
    window.addEventListener('resize', syncImAppbarBack);
    document.addEventListener('click', onImAppbarBack);

    MessengerPage.prototype.render = async function vkifyMessengerPageRender(container, options = {}, messenger = null) {
        if (!container) {
            console.error('vkify16 | MessengerPage.render called without container');
            return;
        }

        const orig_messenger = messenger || window.im?.messenger;
        if (!orig_messenger) {
            console.error('vkify16 | MessengerPage.render: no messenger');
            return;
        }

        try {
            const result = await vkifyRenderMessenger.call(this, container, options, orig_messenger, {
                html, render, h, Fragment, ErrorConversation, MessageListView,
                ActionsBar: VkActionsBar, PeerInfoView, PinnedMessageBar, InputAreaComponent,
            });
            lastRenderError = null;
            return result;
        } catch (e) {
            logRenderErrorOnce('vkify16 | messenger render failed, falling back to upstream:', e);
            try {
                render(null, container);
            } catch (_) {
            }
            if (typeof origMessengerRender === 'function') {
                try {
                    const fallbackResult = await origMessengerRender.call(this, container, options, messenger);
                    lastRenderError = null;
                    return fallbackResult;
                } catch (e2) {
                    logRenderErrorOnce('vkify16 | upstream fallback render also failed:', e2);
                }
            }
        }
    };

    function peerTabsSignature(messenger) {
        try {
            const tabs = Array.isArray(messenger && messenger.opened_tabs) ? messenger.opened_tabs : [];
            const ids = tabs.map((t) => {
                const id = (t && t.peer && t.peer.id != null) ? t.peer.id : ((t && t.id != null) ? t.id : '');
                return String(id) + ':' + String(t?.unread_count || 0) + ':' + String(t?.isRead?.() ?? true);
            });
            return ids.join(',') + '|' + String(messenger && messenger.currentChatId != null ? messenger.currentChatId : '');
        } catch (e) {
            return '';
        }
    }

    function refreshPeerTabs(messenger) {
        const page = window.im?.getTab?.('messenger')?.render_class;
        if (!page || window.im?.getSelectedTabId?.() !== 'messenger' || isCompactMode(window.im)) return;
        const sig = peerTabsSignature(messenger);
        if (sig !== page._vkifyLastPeerTabsSig) {
            page._vkifyLastPeerTabsSig = sig;
            window.im?.updateTabs?.();
        }
    }

    async function vkifyRenderMessenger(container, options, orig_messenger, deps) {
        const { html, render, h, Fragment, ErrorConversation, MessageListView, ActionsBar, PeerInfoView, PinnedMessageBar, InputAreaComponent } = deps;
        try {
            orig_messenger.currentDraft = this.getCurrentText() || '';
        } catch (e) {
        }
        syncBodyNoScroll();

        this.getNode().addClass('page-other');

        // While forwarding, upstream shows the empty-state hint in the chat pane.
        const convTab = window.im?.tabs?.find(t => t.getPageId() === 'conversations');
        if (convTab?.options?.forward?.length > 0) {
            const onCancel = () => convTab.render_class?.onCancelForward?.();
            render(html`<${VkEmptyConversation} isForward=${true} onCancel=${onCancel} />`, container);
            return;
        }

        const currentConv = orig_messenger.getCurrentChat();
        if (!currentConv) {
            render(html`<${VkEmptyConversation} />`, container);
            return;
        }

        const peer = currentConv.peer;
        const sp = currentConv.getScrollPosition();
        let messages = null;
        if (peer && typeof peer.isMessagesInited === 'function' && peer.isMessagesInited() && sp) {
            messages = sp.getDayDividedMessages();
        }
        ensureVideoPreviews(messages);

        const isSavedMessages = peer && peer.id == window.im?.state?.getId();
        // Upstream keeps the visible date across re-renders (this.currentVisibleDate);
        // fall back to the last chunk date like upstream render does.
        const initialDate = this.currentVisibleDate || ((messages && messages.length > 0)
            ? (messages[messages.length - 1].readable_date || messages[messages.length - 1].date || '')
            : '');

        const pinned = (currentConv.hasPinned && currentConv.hasPinned())
            ? html`<${PinnedMessageBar} convo=${currentConv} />`
            : null;
        const headerWrapClass = 'messenger-app--header-wrap' + (pinned ? ' has-pinned' : '');

        const chatPage = html`
            <div id="chat-page">
                <div class="chat-window ${isSavedMessages ? 'saved-msgs' : ''}">
                    <div class=${headerWrapClass}>
                        <${PeerInfoView}
                            convo=${currentConv}
                            page=${this}
                            togglePeerInfo=${() => { this.togglePeerInfo(); }}
                        />
                        ${pinned}
                    </div>
                    <${ActionsBar}
                        selectedMessages=${orig_messenger.selected_messages_objs}
                        count=${orig_messenger.selected_messages_count}
                        onDelete=${() => this.callDeletion()}
                        onUnselect=${() => orig_messenger.unselectAll()}
                        onReply=${() => this.onReplyButtonClick()}
                        onForwardClick=${() => this.onForwardClick()}
                        onViewers=${(msg) => this.onViewersButtonClick(null, msg || orig_messenger.selected_messages_objs[0])}
                        onPin=${(msg) => this.onPinButtonClick(null, msg || orig_messenger.selected_messages_objs[0])}
                        onReport=${(msg) => this.onReportButtonClick(null, msg || orig_messenger.selected_messages_objs[0])}
                    />
                    <div class="messenger-app messenger-layer">
                        ${initialDate ? html`
                            <div class="im_floating_date_wrap" onClick=${(e) => this.onFloatingDateClick(e)}>
                                <b id="im_floating_date_text">${initialDate}</b>
                            </div>
                        ` : ''}
                        <${MessageListView}
                            convo=${currentConv}
                            dayDividedChunks=${messages}
                            page=${this} />
                        ${!options.removeInput ? html`<${InputAreaComponent}
                            convo=${currentConv}
                            editMsg=${orig_messenger.editMsg}
                            replyTo=${orig_messenger.replyTo}
                            onRemoveReply=${() => orig_messenger.removeReply()}
                            onSend=${() => orig_messenger.onSendMessage()}
                            onKeyPress=${(e) => this.onTextareaKeyPress(e)}
                            currentDraft=${orig_messenger.currentDraft}
                            onInput=${(e) => {
                                const val = (e && e.target && (e.target.value !== undefined
                                    ? e.target.value
                                    : (e.target._contentEditable ? e.target._contentEditable.getText() : e.target.innerText))) || '';
                                this.currentDraft = val;
                                orig_messenger.currentDraft = val;
                                try {
                                    this.checkMentionTrigger(e.target);
                                } catch (err) {
                                    console.error('vkify16 | checkMentionTrigger failed:', err);
                                }
                            }}
                            togglePeerInfo=${(e) => { this.togglePeerInfo(); }}
                            clickOnReply=${(msg, e) => { this.clickOnReply(msg, e); }}
                            forwarded_msg=${orig_messenger.forwarded_msg}
                            onRemoveForward=${() => orig_messenger.removeForward()}
                            mentionActive=${orig_messenger.mentionActive}
                            mentionMatches=${orig_messenger.mentionMatches}
                            mentionSelectedIndex=${orig_messenger.mentionSelectedIndex}
                            onApplyMention=${(item) => { this.applyMention(item); }}
                        />` : ''}
                    </div>
                </div>
            </div>
        `;

        render(chatPage, container);
        syncImAppbarBack();
        syncAttachmentLoaders(container);

        // Mirror upstream showHook/render side effects; guarded for older upstream.
        try {
            if (typeof this.updateMountainButton === 'function') this.updateMountainButton();
        } catch (e) {
            console.error('vkify16 | updateMountainButton failed:', e);
        }
        try {
            if (typeof this._setupReadObserver === 'function') this._setupReadObserver();
        } catch (e) {
            console.error('vkify16 | _setupReadObserver failed:', e);
        }
        try {
            if (typeof this._setupVisibilityListener === 'function') this._setupVisibilityListener();
        } catch (e) {
            console.error('vkify16 | _setupVisibilityListener failed:', e);
        }
        try {
            if (typeof this._setupResizeListener === 'function') this._setupResizeListener();
        } catch (e) {
            console.error('vkify16 | _setupResizeListener failed:', e);
        }
        try {
            if (typeof this._checkAndFillUnderflow === 'function') this._checkAndFillUnderflow();
        } catch (e) {
            console.error('vkify16 | _checkAndFillUnderflow failed:', e);
        }
        try {
            this._updPadding();
        } catch (e) {
            console.error('vkify16 | _updPadding failed:', e);
        }

        // The tab bar lives outside the chat render; refresh only when its data changes.
        try {
            refreshPeerTabs(orig_messenger);
        } catch (e) {
            console.error('vkify16 | tab bar refresh failed:', e);
        }
    }

    MessengerPage.prototype.getCurrentAttachments = function vkifyGetCurrentAttachments() {
        try {
            if (typeof origGetCurrentAttachments === 'function') {
                const orig = origGetCurrentAttachments.call(this);
                if (orig && (orig[0] || orig[1])) {
                    return orig;
                }
            }
        } catch (e) {
        }
        const h = this.container ? this.container.querySelector('.post-horizontal') : null;
        const v = this.container ? this.container.querySelector('.post-vertical') : null;
        return [h ? h.innerHTML : '', v ? v.innerHTML : ''];
    };

    const origTogglePeerInfo = MessengerPage.prototype.togglePeerInfo;

    // Upstream 5796d6fa no-oped togglePeerInfo; restore the open/close toggle.
    MessengerPage.prototype.togglePeerInfo = async function vkifyTogglePeerInfo(sender = null) {
        const messenger = window.im?.messenger;
        if (!messenger || messenger.is_switching === true) {
            return;
        }
        messenger.is_switching = true;
        try {
            if (window.im.getSelectedTabId?.() == "contact") {
                const contactTab = window.im.getTab?.("contact");
                if (contactTab) {
                    contactTab.close();
                }
                window.im.openTabByName('messenger');
            } else {
                const _c = window.im.state?.getCurrentConvo?.();
                if (_c?.peer && !(typeof _c.peer.isILeft === 'function' && _c.peer.isILeft())) {
                    await _c.peer.checkMembers?.();
                }
                window.im.openTabByName?.('contact', false, {
                    peer: { "peer": sender }
                });
            }
        } catch (e) {
            console.error('vkify16 | togglePeerInfo failed, deferring to upstream:', e);
            if (typeof origTogglePeerInfo === 'function') {
                try {
                    return await origTogglePeerInfo.call(this, sender);
                } catch (e2) {
                    console.error('vkify16 | upstream togglePeerInfo also failed:', e2);
                }
            }
        } finally {
            messenger.is_switching = false;
        }
    };

    const origToggleMessageSelection = MessengerPage.prototype.toggleMessageSelection;

    MessengerPage.prototype.toggleMessageSelection = function vkifyToggleMessageSelection(msg, e) {
        const isMobile = Boolean(window.im?.state?.is_mobile || document.body.classList.contains('im_mobile'));
        if (!isMobile || typeof origToggleMessageSelection !== 'function') {
            return origToggleMessageSelection?.call(this, msg, e);
        }

        const messenger = window.im?.messenger;
        if (!messenger || msg.isDeleted() || messenger.isForwarded()) {
            return;
        }

        if (msg.id == null || !(Number(msg.id) > 0)) {
            if (!e?.target?.closest?.(".error-checkmark")) {
                new CMessageBox({
                    title: tr("confirm"),
                    body: tr("cancel_sending_confirmation"),
                    buttons: [tr("yes"), tr("no")],
                    callbacks: [() => {
                        msg.setDeleted();
                        this._triggerUpdate();
                    }, () => { }]
                });
                return;
            }
        }

        if (messenger.isEditing()) {
            this._triggerCancelEditingDialog();
            return;
        }

        const msgEl = e?.target?.closest?.('.messenger-app--messages---message') ?? null;
        if (msgEl?.classList.contains('has-active-dropdown')) {
            return;
        }

        const rect = msgEl?.getBoundingClientRect();
        this.activeDropdownOpenUp = rect ? (window.innerHeight - rect.bottom) < 230 : false;
        this.activeDropdownMsgId = msg.id;
        this.update();
    };

}
